using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class BuildAttackRecovery20
{
 class Pose{public Vector3[] p,s;public Quaternion[] q;}
 static Pose Capture(Transform[] ts)=>new Pose{p=ts.Select(t=>t.localPosition).ToArray(),q=ts.Select(t=>t.localRotation).ToArray(),s=ts.Select(t=>t.localScale).ToArray()};
 static void Apply(Transform[] ts,Pose p){for(int i=0;i<ts.Length;i++){ts[i].localPosition=p.p[i];ts[i].localRotation=p.q[i];ts[i].localScale=p.s[i];}}
 static AnimationClip Make(string name,string[] paths,List<Pose> poses,float duration){var clip=new AnimationClip{name=name,frameRate=30};var bs=new List<EditorCurveBinding>();var cs=new List<AnimationCurve>();for(int n=0;n<paths.Length;n++){for(int f=1;f<poses.Count;f++)if(Quaternion.Dot(poses[f-1].q[n],poses[f].q[n])<0){var q=poses[f].q[n];poses[f].q[n]=new Quaternion(-q.x,-q.y,-q.z,-q.w);}for(int c=0;c<10;c++){var curve=new AnimationCurve(poses.Select((p,f)=>new Keyframe(duration*f/(poses.Count-1),c<3?p.p[n][c]:c<7?p.q[n][c-3]:p.s[n][c-7])).ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,k,AnimationUtility.TangentMode.Linear);}bs.Add(EditorCurveBinding.FloatCurve(paths[n],typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:c<7?"m_LocalRotation."+"xyzw"[c-3]:"m_LocalScale."+"xyz"[c-7]));cs.Add(curve);}}AnimationUtility.SetEditorCurves(clip,bs.ToArray(),cs.ToArray());var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=false;settings.loopBlend=false;AnimationUtility.SetAnimationClipSettings(clip,settings);return clip;}
 static float Floor(SkinnedMeshRenderer skin){var mesh=skin.sharedMesh;var vs=mesh.vertices;var ws=mesh.boneWeights;var mats=skin.bones.Select((b,i)=>b.localToWorldMatrix*mesh.bindposes[i]).ToArray();float y=float.PositiveInfinity;for(int i=0;i<vs.Length;i++){var w=ws[i];var p=mats[w.boneIndex0].MultiplyPoint3x4(vs[i])*w.weight0+mats[w.boneIndex1].MultiplyPoint3x4(vs[i])*w.weight1+mats[w.boneIndex2].MultiplyPoint3x4(vs[i])*w.weight2+mats[w.boneIndex3].MultiplyPoint3x4(vs[i])*w.weight3;y=Mathf.Min(y,p.y);}return y;}
 public static object Run()
 {
  if(Application.isPlaying)throw new Exception("Stop play first");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="3DBattleDebugScene")throw new Exception("Wrong scene");foreach(var w in Resources.FindObjectsOfTypeAll<AnimationWindow>()){w.recording=false;w.previewing=false;}if(AnimationMode.InAnimationMode())AnimationMode.StopAnimationMode();
  string[] names={"Attack 01 - Attack","Attack 02 - Charged_Upward_Slash","Attack 03 - Double_Combo_Attack","Attack 04 - Right_Hand_Sword_Slash","Attack 05 - Skill_03","Attack 06 - Weapon_Combo_1"};int[] ends={84,95,85,45,16,61};var live=names.Select(GameObject.Find).ToArray();var clips=live.Select(g=>g.GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0]).ToArray();for(int i=0;i<6;i++)if(Mathf.Abs(clips[i].length*30-ends[i])>.01f)throw new Exception("Unexpected source length: "+names[i]);
  var combo=GameObject.Find("New Knight Combo Sequence Preview").GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0];string comboBefore=EditorJsonUtility.ToJson(combo);
  var paths=clips.SelectMany(c=>AnimationUtility.GetCurveBindings(c)).Select(b=>b.path).Distinct().OrderBy(p=>p.Count(ch=>ch=='/')).ToArray();var template=UnityEngine.Object.Instantiate(live[0]);template.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var ta=template.GetComponentInChildren<Animator>();ta.enabled=false;var nodes=paths.Select(p=>ta.transform.Find(p)).ToArray();var skin=template.GetComponentInChildren<SkinnedMeshRenderer>();var bones=skin.bones.OrderBy(b=>AnimationUtility.CalculateTransformPath(b,ta.transform).Count(ch=>ch=='/')).ToArray();var hip=bones.First(b=>b.name=="Hips");int hi=Array.IndexOf(nodes,hip);var sword=template.GetComponentsInChildren<Transform>().First(t=>t.name=="Sword");int si=Array.IndexOf(nodes,sword);clips[0].SampleAnimation(ta.gameObject,0);Vector3 swordMountPosition=sword.localPosition;Quaternion swordMountRotation=sword.localRotation;
  var player=UnityEngine.Object.FindFirstObjectByType<BattlePlayerController>();var reference=UnityEngine.Object.Instantiate(player.gameObject);reference.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var behaviour in reference.GetComponentsInChildren<MonoBehaviour>(true))behaviour.enabled=false;var ra=reference.GetComponent<BattlePlayerController>().animator;ra.enabled=false;var rs=ra.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.name=="Knight");var idle=ra.runtimeAnimatorController.animationClips.First(c=>c.name.EndsWith("Idle_swordRight"));var sourceBones=rs.bones.ToDictionary(b=>b.name);var sb=rs.bones.Select((b,i)=>new{b.name,m=rs.transform.localToWorldMatrix*rs.sharedMesh.bindposes[i].inverse}).ToDictionary(x=>x.name,x=>x.m);var db=skin.bones.Select((b,i)=>new{b.name,m=skin.transform.localToWorldMatrix*skin.sharedMesh.bindposes[i].inverse}).ToDictionary(x=>x.name,x=>x.m);
  var map=new Dictionary<string,string>{{"Hips","Hips"},{"Chest","Abdomen"},{"UpperChest","Torso"},{"Neck","Neck"},{"Head","Head"}};foreach(string side in new[]{"Left","Right"}){string suffix=side=="Left"?".L":".R";foreach(var pair in new[]{new[]{"Shoulder","Shoulder"},new[]{"UpperArm","UpperArm"},new[]{"LowerArm","LowerArm"},new[]{"Hand","Palm"},new[]{"UpperLeg","UpperLeg"},new[]{"LowerLeg","LowerLeg"},new[]{"Foot","Foot"},new[]{"Toes","Foot"}})map[side+pair[0]]=pair[1]+suffix;}
  var errors=new List<string>();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);};Application.logMessageReceived+=log;var generated=new List<AnimationClip>();var reports=new List<object>();
  try{
   idle.SampleAnimation(ra.gameObject,0);foreach(var b in bones)b.SetPositionAndRotation(db[b.name].GetColumn(3),db[b.name].rotation);foreach(var b in bones){string src=map[b.name];b.rotation=sourceBones[src].rotation*Quaternion.Inverse(sb[src].rotation)*db[b.name].rotation;}
   // Retain the closed right-hand grip while matching the gameplay idle sword direction.
   var oldSword=reference.GetComponentsInChildren<MeshRenderer>(true).First(r=>r.name=="Sword").transform;var hand=bones.First(b=>b.name=="RightHand");hand.rotation=oldSword.rotation*Quaternion.Inverse(swordMountRotation);sword.localPosition=swordMountPosition;sword.localRotation=swordMountRotation;hip.position+=Vector3.up*(.015f-Floor(skin));var idlePose=Capture(nodes);Vector3 idleWorldHip=hip.position;
   const string folder="Assets/3DBattle/NewPlayer/Attack/Recovery20";if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets/3DBattle/NewPlayer/Attack","Recovery20");var idleClip=Make("NewKnight_IdleReady",paths,new List<Pose>{Capture(nodes),Capture(nodes)},1f/30);AssetDatabase.CreateAsset(idleClip,AssetDatabase.GenerateUniqueAssetPath(folder+"/NewKnight_IdleReady.anim"));
   for(int i=0;i<6;i++){
    var root=UnityEngine.Object.Instantiate(live[i]);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);try{var a=root.GetComponentInChildren<Animator>();a.enabled=false;var ts=paths.Select(p=>a.transform.Find(p)).ToArray();var h=ts[hi];clips[i].SampleAnimation(a.gameObject,ends[i]/30f);var end=Capture(ts);Vector3 endWorldHip=h.position;Apply(ts,idlePose);h.position=new Vector3(endWorldHip.x,idleWorldHip.y,endWorldHip.z);var target=Capture(ts);var samples=new List<Pose>();float maxHorizontalDrift=0;int final=ends[i]+20;
     for(int half=0;half<=final*2;half++){float frame=half*.5f;if(frame<=ends[i])clips[i].SampleAnimation(a.gameObject,frame/30f);else{float u=Mathf.SmoothStep(0,1,(frame-ends[i])/20f);for(int j=0;j<ts.Length;j++){ts[j].localPosition=Vector3.Lerp(end.p[j],target.p[j],u);ts[j].localRotation=Quaternion.Slerp(end.q[j],target.q[j],u);ts[j].localScale=Vector3.Lerp(end.s[j],target.s[j],u);}maxHorizontalDrift=Mathf.Max(maxHorizontalDrift,Vector3.ProjectOnPlane(h.position-endWorldHip,Vector3.up).magnitude);}samples.Add(Capture(ts));}
     var output=Make("NewKnight_"+names[i].Split(new[]{" - "},StringSplitOptions.None)[1]+"_Return20",paths,samples,final/30f);float poseError=0,rotError=0;for(int f=0;f<=ends[i];f++){clips[i].SampleAnimation(a.gameObject,f/30f);var before=Capture(ts);output.SampleAnimation(a.gameObject,f/30f);for(int j=0;j<ts.Length;j++){poseError=Mathf.Max(poseError,Vector3.Distance(before.p[j],ts[j].localPosition));rotError=Mathf.Max(rotError,Quaternion.Angle(before.q[j],ts[j].localRotation));}}output.SampleAnimation(a.gameObject,final/30f);float finalError=0;for(int j=0;j<ts.Length;j++)finalError=Mathf.Max(finalError,Quaternion.Angle(target.q[j],ts[j].localRotation));if(poseError>.001f||rotError>.1f||finalError>.1f||maxHorizontalDrift>.001f||errors.Count>0)throw new Exception("Recovery validation failed "+names[i]+" "+string.Join("|",errors));AssetDatabase.CreateAsset(output,AssetDatabase.GenerateUniqueAssetPath(folder+"/"+output.name+".anim"));generated.Add(output);reports.Add(new{name=names[i],originalEnd=ends[i],recoveryFirst=ends[i]+1,recoveryLast=final,addedFrames=20,originalPositionError=poseError,originalRotationError=rotError,finalPoseError=finalError,horizontalDrift=maxHorizontalDrift});
    }finally{UnityEngine.Object.DestroyImmediate(root);}
   }
   AssetDatabase.SaveAssets();for(int i=0;i<6;i++){var ctrl=AnimatorController.CreateAnimatorControllerAtPath(AssetDatabase.GenerateUniqueAssetPath(folder+"/"+generated[i].name+".controller"));var state=ctrl.layers[0].stateMachine.AddState("Attack and return to idle");state.motion=generated[i];ctrl.layers[0].stateMachine.defaultState=state;var a=live[i].GetComponentInChildren<Animator>();Undo.RecordObject(a,"Append 20 frame recovery");a.runtimeAnimatorController=ctrl;generated[i].SampleAnimation(a.gameObject,0);}AssetDatabase.SaveAssets();if(comboBefore!=EditorJsonUtility.ToJson(combo))throw new Exception("Combo changed");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var report=new{idleReference=idle.name,comboUnchanged=true,recoveries=reports};AssetDatabase.CreateAsset(new TextAsset(Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented)){name="Recovery20_FrameRanges"},AssetDatabase.GenerateUniqueAssetPath(folder+"/Recovery20_FrameRanges.asset"));AssetDatabase.SaveAssets();return report;
  }finally{Application.logMessageReceived-=log;UnityEngine.Object.DestroyImmediate(reference);UnityEngine.Object.DestroyImmediate(template);}
 }
